 IF EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='wishes' AND (catalog_hash<>'e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4' OR payload_md5<>'2df570fb05e93974e4b74ffbd5b9c5a5')) THEN RAISE EXCEPTION 'Catalog payload conflict: use a new version'; END IF;
