INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','wishes','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"wishes","title":"Wishes, regrets and if only","level":"B2","order":44,"summary":"Express a desired change in the present, regret about the past or dissatisfaction with someone’s behaviour.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["An unreal present wish","Regret about the past","A wish for changed behaviour","Ability and wishes"],"rules":[{"title":"An unreal present wish","explanation":"After wish or if only, use a past form to imagine a present situation differently. This is sometimes called unreal past: its form is past, but its reference can be now. With be, were is common for all persons in formal hypothetical uses.","pattern":"I wish I **knew** the answer. / If only I **were** taller.","commonMistakes":["A future hope that may come true normally uses hope, not wish + will in the same pattern."],"examples":["Use a past form for an unreal present wish: “I wish she **prepared** the visitor guide more often.”","Use a past form for an unreal present wish: “I wish she **restored** the old portrait more often.”"],"skill":"form"},{"title":"Regret about the past","explanation":"Use **wish + past perfect** to regret an earlier event or non-event. The past perfect marks the fact that the past cannot now be changed. The wish describes an alternative to it.","pattern":"I wish I **had checked** the time.","commonMistakes":["I wish I checked yesterday does not give the standard past-regret form; use had checked."],"examples":["The task was not done yesterday: “I wish I **had prepared** the visitor guide then.”","The task was not done yesterday: “I wish I **had restored** the old portrait then.”"],"skill":"meaning"},{"title":"A wish for changed behaviour","explanation":"Wish + would often expresses a desire for another person or an external situation to change, especially an irritating repeated behaviour. It normally concerns willingness or behaviour, rather than a simple characteristic.","pattern":"I wish they **would listen**.","commonMistakes":["I wish I would be taller is not the normal way to wish for a different characteristic."],"examples":["You want someone to change an annoying habit: “I wish they would **prepare** the visitor guide without being asked.”","You want someone to change an annoying habit: “I wish they would **restore** the old portrait without being asked.”"],"skill":"contrast"},{"title":"Ability and wishes","explanation":"Wish + could can express a desired ability or opportunity. Compare I wish I could come with I hope I can come: the former suggests a barrier, while the latter leaves the possibility open. If only usually makes the wish more emphatic.","pattern":"If only I **could stay** longer.","commonMistakes":["Choose wish or hope from the speaker’s view of reality, not just from whether the sentence refers to the future."],"examples":["You lack the ability: “If only I could **prepare** the visitor guide by myself.”","You lack the ability: “If only I could **restore** the old portrait by myself.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"97226c2d-d301-55b9-aab0-213ef8ddbab8","topicSlug":"wishes","level":"B2","prompt":"Use a past form for an unreal present wish: “I wish she ____ the visitor guide more often.”","choices":[{"id":"A","text":"prepared"},{"id":"B","text":"prepares"},{"id":"C","text":"preparing"},{"id":"D","text":"to prepare"}],"answerId":"A","hint":"This is an **unreal present wish**; past form marks distance from reality.","explanation":"The wish imagines a different present habit, so it uses past-form **prepared**.","keywords":["present-wish"],"skill":"present-wish","contextKey":"wishes-1","fingerprint":"28a616cf5c663c45b04aa8a39c038d5852f6b165f4ff7af2ad2a19dfd087cd37","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["This is an **unreal present wish**; past form marks distance from reality.","The wish imagines a different present habit, so it uses past-form **prepared**.","Choose **prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The wish imagines a different present habit, so it uses past-form **prepared**.","B":"The ordinary unreal-present wish uses a past form rather than present -s.","C":"An -ing form alone cannot complete the finite clause.","D":"A to-infinitive does not supply the finite predicate after she."}}},{"id":"5313f7ec-72a4-5731-a09f-5a430fe112e5","topicSlug":"wishes","level":"B2","prompt":"The task was not done yesterday: “I wish I ____ the visitor guide then.”","choices":[{"id":"A","text":"had preparing"},{"id":"B","text":"would prepare"},{"id":"C","text":"had prepared"},{"id":"D","text":"have prepared"}],"answerId":"C","hint":"The time **then** refers to a finished past; use **past perfect** for the regret.","explanation":"A regret about yesterday uses **had + prepared** after wish.","keywords":["past-regret"],"skill":"past-regret","contextKey":"wishes-1","fingerprint":"8efccc2ff2d8d38f641bece4dab0785b51d83edd09c01e3d5350ac36bbb0dd42","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The time **then** refers to a finished past; use **past perfect** for the regret.","A regret about yesterday uses **had + prepared** after wish.","Choose **had prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Had needs a past participle here, not -ing.","B":"Would + base normally asks for changed behaviour rather than rewriting a finished past event.","C":"A regret about yesterday uses **had + prepared** after wish.","D":"Present perfect is not the standard past-regret form after wish."}}},{"id":"7e72c03a-fb26-5174-a697-72a05b1fd6eb","topicSlug":"wishes","level":"B2","prompt":"You want someone to change an annoying habit: “I wish they would ____ the visitor guide without being asked.”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"prepare"},{"id":"C","text":"prepares"},{"id":"D","text":"prepared"}],"answerId":"B","hint":"The change is expressed by **would + base verb**.","explanation":"After **would**, keep base **prepare** for the desired change in behaviour.","keywords":["wish-behaviour"],"skill":"wish-behaviour","contextKey":"wishes-1","fingerprint":"bfe91b4648cd2b1693b1731fed01a939650660e9ab84f801904074f20bf34b42","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The change is expressed by **would + base verb**.","After **would**, keep base **prepare** for the desired change in behaviour.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Would takes a bare infinitive without to.","B":"After **would**, keep base **prepare** for the desired change in behaviour.","C":"Would takes a base form without -s.","D":"A past form cannot directly follow would."}}},{"id":"b8d60bc7-e97d-57b3-a42d-b23acae29b2a","topicSlug":"wishes","level":"B2","prompt":"You lack the ability: “If only I could ____ the visitor guide by myself.”","choices":[{"id":"A","text":"prepares"},{"id":"B","text":"to prepare"},{"id":"C","text":"prepare"},{"id":"D","text":"preparing"}],"answerId":"C","hint":"Could already marks the desired ability; use the **base verb** after it.","explanation":"**Could + prepare** expresses the wished-for ability.","keywords":["wish-ability"],"skill":"wish-ability","contextKey":"wishes-1","fingerprint":"5b4d38a19002687225f401ddeb5d20a78832eaae312cf19c5e9d045c9d42371e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Could already marks the desired ability; use the **base verb** after it.","**Could + prepare** expresses the wished-for ability.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Could does not take third-person -s on the next verb.","B":"Could takes a bare infinitive.","C":"**Could + prepare** expresses the wished-for ability.","D":"Could alone does not take -ing."}}},{"id":"0d97ac08-d73a-5461-a48c-b6d92069286a","topicSlug":"wishes","level":"B2","prompt":"Use a past form for an unreal present wish: “I wish she ____ the old portrait more often.”","choices":[{"id":"A","text":"to restore"},{"id":"B","text":"restored"},{"id":"C","text":"restores"},{"id":"D","text":"restoring"}],"answerId":"B","hint":"This is an **unreal present wish**; past form marks distance from reality.","explanation":"The wish imagines a different present habit, so it uses past-form **restored**.","keywords":["present-wish"],"skill":"present-wish","contextKey":"wishes-2","fingerprint":"a9e1656f04ddfa8cb6bc8e638285c7f96030d04f1dcf65983aac9f1bf7d90113","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["This is an **unreal present wish**; past form marks distance from reality.","The wish imagines a different present habit, so it uses past-form **restored**.","Choose **restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive does not supply the finite predicate after she.","B":"The wish imagines a different present habit, so it uses past-form **restored**.","C":"The ordinary unreal-present wish uses a past form rather than present -s.","D":"An -ing form alone cannot complete the finite clause."}}},{"id":"8c54e716-fe6d-5ad1-a2d2-2dd264436692","topicSlug":"wishes","level":"B2","prompt":"The task was not done yesterday: “I wish I ____ the old portrait then.”","choices":[{"id":"A","text":"have restored"},{"id":"B","text":"had restoring"},{"id":"C","text":"would restore"},{"id":"D","text":"had restored"}],"answerId":"D","hint":"The time **then** refers to a finished past; use **past perfect** for the regret.","explanation":"A regret about yesterday uses **had + restored** after wish.","keywords":["past-regret"],"skill":"past-regret","contextKey":"wishes-2","fingerprint":"c4bb95247e368bfca05797861fe9920320df954709558ff23c683e99b49c1eea","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The time **then** refers to a finished past; use **past perfect** for the regret.","A regret about yesterday uses **had + restored** after wish.","Choose **had restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Present perfect is not the standard past-regret form after wish.","B":"Had needs a past participle here, not -ing.","C":"Would + base normally asks for changed behaviour rather than rewriting a finished past event.","D":"A regret about yesterday uses **had + restored** after wish."}}},{"id":"d415cd0e-2c2f-5e21-ae4c-aeaf3a1dd847","topicSlug":"wishes","level":"B2","prompt":"You want someone to change an annoying habit: “I wish they would ____ the old portrait without being asked.”","choices":[{"id":"A","text":"restore"},{"id":"B","text":"restores"},{"id":"C","text":"restored"},{"id":"D","text":"to restore"}],"answerId":"A","hint":"The change is expressed by **would + base verb**.","explanation":"After **would**, keep base **restore** for the desired change in behaviour.","keywords":["wish-behaviour"],"skill":"wish-behaviour","contextKey":"wishes-2","fingerprint":"9fc3fbfd2e43aff1f26c7e376812fb1523dafc41c58b4ebcd2482bf633194135","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The change is expressed by **would + base verb**.","After **would**, keep base **restore** for the desired change in behaviour.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After **would**, keep base **restore** for the desired change in behaviour.","B":"Would takes a base form without -s.","C":"A past form cannot directly follow would.","D":"Would takes a bare infinitive without to."}}},{"id":"27cd2404-da10-54cc-a312-9e9f4609bdac","topicSlug":"wishes","level":"B2","prompt":"You lack the ability: “If only I could ____ the old portrait by myself.”","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"restores"},{"id":"C","text":"to restore"},{"id":"D","text":"restore"}],"answerId":"D","hint":"Could already marks the desired ability; use the **base verb** after it.","explanation":"**Could + restore** expresses the wished-for ability.","keywords":["wish-ability"],"skill":"wish-ability","contextKey":"wishes-2","fingerprint":"62941ea36918e6bf2b761c9752cafef4f276e312e4df9c5c5dd37d0a6e01586c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Could already marks the desired ability; use the **base verb** after it.","**Could + restore** expresses the wished-for ability.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Could alone does not take -ing.","B":"Could does not take third-person -s on the next verb.","C":"Could takes a bare infinitive.","D":"**Could + restore** expresses the wished-for ability."}}},{"id":"c5476dca-1461-50ed-a549-78633d5855b1","topicSlug":"wishes","level":"B2","prompt":"Use a past form for an unreal present wish: “I wish she ____ the garden fence more often.”","choices":[{"id":"A","text":"measures"},{"id":"B","text":"measuring"},{"id":"C","text":"to measure"},{"id":"D","text":"measured"}],"answerId":"D","hint":"This is an **unreal present wish**; past form marks distance from reality.","explanation":"The wish imagines a different present habit, so it uses past-form **measured**.","keywords":["present-wish"],"skill":"present-wish","contextKey":"wishes-3","fingerprint":"e8dd133a9b2fe7876fcb8246ae771e5a152e67db116d05846216fd41e0c556d7","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["This is an **unreal present wish**; past form marks distance from reality.","The wish imagines a different present habit, so it uses past-form **measured**.","Choose **measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The ordinary unreal-present wish uses a past form rather than present -s.","B":"An -ing form alone cannot complete the finite clause.","C":"A to-infinitive does not supply the finite predicate after she.","D":"The wish imagines a different present habit, so it uses past-form **measured**."}}},{"id":"890d8ad7-2ef5-5bfb-a269-931b6801b9a3","topicSlug":"wishes","level":"B2","prompt":"The task was not done yesterday: “I wish I ____ the garden fence then.”","choices":[{"id":"A","text":"have measured"},{"id":"B","text":"had measuring"},{"id":"C","text":"would measure"},{"id":"D","text":"had measured"}],"answerId":"D","hint":"The time **then** refers to a finished past; use **past perfect** for the regret.","explanation":"A regret about yesterday uses **had + measured** after wish.","keywords":["past-regret"],"skill":"past-regret","contextKey":"wishes-3","fingerprint":"b43925c790eff4d7dccbc459850c96da1740755bf1df7182fe49d7732c3ff6d7","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The time **then** refers to a finished past; use **past perfect** for the regret.","A regret about yesterday uses **had + measured** after wish.","Choose **had measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Present perfect is not the standard past-regret form after wish.","B":"Had needs a past participle here, not -ing.","C":"Would + base normally asks for changed behaviour rather than rewriting a finished past event.","D":"A regret about yesterday uses **had + measured** after wish."}}},{"id":"69f9f307-1d66-5494-a719-88778332face","topicSlug":"wishes","level":"B2","prompt":"You want someone to change an annoying habit: “I wish they would ____ the garden fence without being asked.”","choices":[{"id":"A","text":"measure"},{"id":"B","text":"measures"},{"id":"C","text":"measured"},{"id":"D","text":"to measure"}],"answerId":"A","hint":"The change is expressed by **would + base verb**.","explanation":"After **would**, keep base **measure** for the desired change in behaviour.","keywords":["wish-behaviour"],"skill":"wish-behaviour","contextKey":"wishes-3","fingerprint":"33f8d5aee0d066571d3ebe006f49eed49423e01459475128424f253362177a29","source":"s